INSERT INTO public.prayer_comments (id, prayer_request_id, member_id, content, author_name, created_at, updated_at) VALUES ('48bfe79c-c009-4f87-bbb7-f8fb5cf238f4', '80000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'Praying for peace and strength for your entire family.', 'Pastor Michael', '2026-08-19 14:08:12.511262+05:30', '2026-08-19 15:08:12.511262+05:30');
INSERT INTO public.prayer_comments (id, prayer_request_id, member_id, content, author_name, created_at, updated_at) VALUES ('b0b7ea10-62ec-403f-890c-82d6b85c5ff6', '80000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', 'Amen! Trust in the Lord with all your heart — He will direct your paths in this new role.', 'Sarah Jenkins', '2026-08-19 11:08:12.511262+05:30', '2026-08-19 15:08:12.511262+05:30');
INSERT INTO public.prayer_comments (id, prayer_request_id, member_id, content, author_name, created_at, updated_at) VALUES ('3e642ada-fb27-411b-96dc-dae549316929', '80000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', 'Praise the Lord! What an incredible testimony of God''s goodness and healing power!', 'Sarah Jenkins', '2026-08-18 21:08:12.511262+05:30', '2026-08-19 15:08:12.511262+05:30');
INSERT INTO public.prayer_comments (id, prayer_request_id, member_id, content, author_name, created_at, updated_at) VALUES ('05d93eb2-32c3-4546-8d79-90076d7e0300', '80000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000002', 'Rejoicing with you! All glory to God!', 'Pastor Michael', '2026-08-19 03:08:12.511262+05:30', '2026-08-19 15:08:12.511262+05:30');
INSERT INTO public.prayer_focuses (id, title, topic, scripture, description, active_date, is_published, archived, created_at, updated_at) VALUES ('90000000-0000-0000-0000-000000000001', 'Global Missions & Outreach', 'Global Missions', '"Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit." — Matthew 28:19', 'Today we are praying for our missionary teams in South America and Southeast Asia. Pray for open doors, protection, and a harvest of souls.', '2026-08-18', true, false, '2026-08-18 20:41:29.170314+05:30', '2026-08-18 20:41:29.170314+05:30');
